using System;using System.Linq;using System.Collections.Generic;using IdleIntelligence.Core;
namespace IdleIntelligence.Runtime {
 public static class ItemDetailsUI {
  public static string EffectName(GameState s,string effect)=>effect=="quantumYield"?UiLocalizedText.Translate("Quantenfunde",s.Settings.language):SettingsRules.Text(s.Settings.language,"effect:"+effect).TrimEnd('.',':',' ');
  public static string Primary(GameState s,ItemInstance item){var d=Workshop.Definition(item);var special=ItemDetailRules.Special(s,item);string effect=d.Role!=""?d.Role:d.Profiles[item.rarity][0];double value=special!=null?(special.Effect=="relay"?special.BonusSeconds:special.INTWeight*100):d.Role!=""?Workshop.DeviceInstance(s,item,d.Role)*100:Workshop.Effect(s,item,effect)*100;string name=EffectName(s,effect);return "<b>"+name+"</b>\n<size=24><color=#"+UnityEngine.ColorUtility.ToHtmlStringRGB(ItemPortrait.RarityColor(item.rarity))+">+"+value.ToString("F2")+(special?.Effect=="relay"?" s":" %")+"</color></size>";}
  public static string Text(GameState s,ItemInstance item,string requestedSlot=null){string lang=s.Settings.language;string T(string key)=>SettingsRules.Text(lang,key);string N(ScientificNumber n)=>NumberFormatting.Format(n,s.Settings.numberFormat,s.Settings.language);string L(string text)=>UiLocalizedText.Translate(text,lang);var d=Workshop.Definition(item);
   var lines=new List<string>{"<b>"+T("item:"+item.type)+"</b>",T("rarity:"+ItemBalance.Rarities[item.rarity])+" · Lv. "+item.level+(item.forge>0?" · "+T("game:forge")+" +"+item.forge:"")};
   var special=ItemDetailRules.Special(s,item);if(special!=null){lines.Add(special.Effect=="relay"?L("Je 10 bezahlte Taps")+": +"+special.BonusSeconds.ToString("F2")+" s "+L("passives Einkommen"):L("INT-Gewichtung")+": +"+(special.INTWeight*100).ToString("F2")+" %");}
   foreach(string effect in d.Profiles[item.rarity].Distinct().Where(e=>e!="relay"&&e!="int-yield"&&e!=d.Role))lines.Add(T("effect:"+effect)+": +"+(Workshop.Effect(s,item,effect)*100).ToString("F2")+" %");
   if(d.Role!="")lines.Add(T("effect:"+d.Role)+": +"+(Workshop.DeviceInstance(s,item,d.Role)*100).ToString("F2")+" % · "+L("Maximum")+" "+(d.Cap*100).ToString("F0")+" %");
   bool worn=s.Workshop.equipped.Contains(item.id);string slot=Workshop.EquipmentSlot(s,item.id,requestedSlot);var p=worn?ItemDetailRules.Upgrade(s,item.id):slot==null?null:new ItemRatePreview{Before=s,After=Workshop.Equip(s,item.id,slot),Slot=slot};
   if(p!=null){var changes=new List<string>();void Metric(string name,ScientificNumber a,ScientificNumber b,bool lower=false){int compare=b.CompareTo(a);if(compare==0||N(a)==N(b))return;bool good=lower?compare<0:compare>0;changes.Add(name+": "+N(a)+" → <color="+(good?"#81F4AD":"#FF929B")+">"+N(b)+"</color>");}
    Metric("Credits/s",Game.Income(p.Before),Game.Income(p.After));Metric(L("Daten")+"/s",Game.DataRate(p.Before),Game.DataRate(p.After));Metric("Compute",Game.Compute(p.Before),Game.Compute(p.After));foreach(string track in new[]{"quality","efficiency"})Metric(T("workshop:"+track)+" · Credits",Game.TrainingCost(p.Before,track),Game.TrainingCost(p.After,track),true);
    foreach(string effect in new[]{"tap","research","experiment","components","drop"}){double a=Workshop.Bonus(p.Before,effect)*100,b=Workshop.Bonus(p.After,effect)*100;if(Math.Abs(a-b)>1e-6)changes.Add(T("effect:"+effect)+": "+a.ToString("F2")+" → <color="+(b>a?"#81F4AD":"#FF929B")+">"+b.ToString("F2")+" %</color>");}
    foreach(string role in ItemBalance.Items.Select(x=>x.Role).Where(x=>x!="").Distinct()){double a=Workshop.Device(p.Before,role)*100,b=Workshop.Device(p.After,role)*100;if(Math.Abs(a-b)>1e-6)changes.Add(EffectName(s,role)+": "+a.ToString("F2")+" → <color="+(b>a?"#81F4AD":"#FF929B")+">"+b.ToString("F2")+" %</color>");}
    // Special mechanics have no immediate production change. Include their actual changed contribution.
    double Contribution(GameState state,string type){var i=Workshop.Equipped(state).FirstOrDefault(x=>x.type==type);if(i==null)return 0;var q=ItemDetailRules.Special(state,i);return q.Effect=="relay"?q.BonusSeconds:q.INTWeight*100;}
    foreach(string type in new[]{"impulse-relay","insight-archive"}){double a=Contribution(p.Before,type),b=Contribution(p.After,type);if(Math.Abs(a-b)>1e-8)changes.Add((type=="impulse-relay"?L("Bonussekunden"):L("INT-Gewichtung"))+": "+a.ToString("F2")+" → <color="+(b>a?"#81F4AD":"#FF929B")+">"+b.ToString("F2")+"</color>");}
    if(changes.Count>0){lines.Add("\n<b>"+L(worn?"Nächstes Level":"Beim Anlegen")+" · "+ItemPortrait.SlotName(p.Slot,lang)+"</b>");lines.AddRange(changes);}
   }return string.Join("\n",lines);
  }
 }
}
